const $=id=>document.getElementById(id),key='omni.siteMode.v1';let store=OmniSiteMode.empty(),pendingOrigin=null;try{const s=JSON.parse(localStorage.getItem(key));if(OmniSiteMode.validate(s))store=s}catch{}
function render(){$('mode').value=store.sites[$('site').value]?.mode||'default';describe();$('list').replaceChildren();for(const [origin,value]of Object.entries(store.sites)){const li=document.createElement('li');li.textContent=new URL(origin).hostname+' · '+value.mode;$('list').append(li)}if(!$('list').children.length){const li=document.createElement('li');li.textContent='All sites use the browser default.';$('list').append(li)}$('reload').disabled=pendingOrigin!==$('site').value}
function describe(){$('description').textContent=$('mode').value==='tv'?'Some sites may offer a TV layout. Sign-in and playback rules still apply.':$('mode').value==='desktop'?'Ask this site for its desktop layout.':'Use the browser’s default desktop layout.'}
async function save(mode){try{const origin=$('site').value,next=OmniSiteMode.set(store,origin,mode);if(window.omnibloomHost?.request){const result=await Promise.race([omnibloomHost.request({version:1,method:'browser.siteMode.write',params:{origin,mode,expectedRevision:store.revision}}),new Promise((_,reject)=>setTimeout(()=>reject(Error('Timed out')),5000))]);if(!result?.ok)throw Error('Not saved')}localStorage.setItem(key,JSON.stringify(next));store=next;pendingOrigin=origin;render();$('status').textContent='Saved. Reload when you are ready.'}catch{$('status').textContent='The change could not be saved. Try again.'}}
$('save').onclick=()=>save($('mode').value);$('reset').onclick=()=>save('default');$('mode').onchange=describe;$('site').onchange=()=>{render();$('status').textContent='Choice shown for this site.'};$('reload').onclick=async()=>{if(window.omnibloomHost?.request){try{const r=await omnibloomHost.request({version:1,method:'browser.siteMode.reload',params:{origin:$('site').value,revision:store.revision}});if(!r?.ok)throw Error();pendingOrigin=null;render();$('status').textContent='Reload requested.'}catch{$('status').textContent='This page could not reload. Open the site again when ready.'}}else{$('status').textContent='Preview saved. The site will reload after browser integration.'}};
let ps=true;$('glyphs').onclick=()=>{ps=!ps;$('glyphs').textContent=ps?'PlayStation hints':'Xbox hints';$('hints').textContent=ps?'D-pad · Move / Cross · Select / Circle · Back':'D-pad · Move / A · Select / B · Back'};window.omniPadController=window.omniMediaController=function(a){const nodes=[...document.querySelectorAll('button,select,summary,input')].filter(e=>!e.disabled&&e.getClientRects().length);const i=nodes.indexOf(document.activeElement),e=document.activeElement;if(['left','right'].includes(a)&&e?.tagName==='SELECT'){e.selectedIndex=Math.max(0,Math.min(e.options.length-1,e.selectedIndex+(a==='left'?-1:1)));e.dispatchEvent(new Event('change'));return true}if(['up','down','left','right'].includes(a)){nodes[(i+(a==='up'||a==='left'?-1:1)+nodes.length)%nodes.length]?.focus();return true}if(a==='confirm'){e?.click();return true}if(a==='back'&&document.querySelector('details').open){document.querySelector('details').open=false;document.querySelector('summary').focus();return true}return false};document.addEventListener('keydown',e=>{const a={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',Escape:'back'}[e.key];if(a&&omniPadController(a))e.preventDefault()});render();
